executeBtn.MouseButton1Click:Connect(function()
	local code = textBox.Text
	if code ~= "" and code ~= "paste script here---- XD" then
		-- Safely compile and call the user script strings via loadstring
		local success, message = pcall(function()
			local func = loadstring(code)
			if func then
				func()
			else
				error("Syntax compilation error inside user environment.")
			end
		end)

		if not success then
			warn("Execution Error: " .. tostring(message))
		end
	end
end)

